import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent

def text(key, style='body', **params):
    return {'kind': 'text', 'key': key, 'style': style, 'params': params}

def notice(key, tone='warning', **params):
    return {'kind': 'notice', 'key': key, 'tone': tone, 'params': params}

def button(key, action='', tone='primary', disabled=False, **params):
    return {'kind': 'button', 'key': key, 'action': action, 'tone': tone, 'disabled': disabled, 'params': params}

def switch(key, on=False, help=None, disabled=False):
    return {'kind': 'switch', 'key': key, 'on': on, 'help': help, 'disabled': disabled}

def input_(key, value='', error=None, disabled=False):
    return {'kind': 'input', 'key': key, 'value': value, 'error': error, 'disabled': disabled}

def choice(key, options, selected=0, disabled=False):
    return {'kind': 'choice', 'key': key, 'options': options, 'selected': selected, 'disabled': disabled}

def image(name='lake', height=260, mode='fit_blur'):
    return {'kind': 'image', 'name': name, 'height': height, 'mode': mode}

def gallery(state='selection', count=6):
    return {'kind': 'gallery', 'state': state, 'count': count}

def summary(selected=24, playable=20):
    return text('library.selection_summary', 'heading', selected=selected, playable=playable)

def state(name, blocks=None, **properties):
    result = {'id': name, **properties}
    if blocks is not None:
        result['blocks'] = blocks
    return result

def row(key, help, action, icon='folder'):
    return {'kind': 'source', 'key': key, 'help': help, 'action': action, 'icon': icon}

P = []

def page(id, title, layout, blocks, states, **props):
    P.append({'id': id, 'title': title, 'layout': layout, 'blocks': blocks, 'states': states, **props})

